pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if necessary.
    // As the stream progresses, favor tighter packing (lower post_residual).
    let mut score = post;

    // Non-linear coupling: penalize creating "dead space" (small post_residual) 
    // that is likely to remain empty, weighted by the remaining stream length.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (1.0 - progress) * (15.0 - post).powf(1.5)
    } else {
        0.0
    };
    score += dead_space_penalty;

    // Lookahead interaction: if next_item_size is large, avoid leaving small residuals
    // that cannot fit the next item.
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.2;
        }
    }

    // Heuristic for new bin: only open a new bin if the current fit is extremely poor
    // or if the residual space is highly fragmented (mean_residual interaction).
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high, but decreases as we reach the end of the stream
        // or if our existing open bins are poorly utilized.
        score = 45.0 + (1.0 - progress) * 20.0;
        if mean_residual > 30.0 {
            score -= 15.0;
        }
    } else {
        // Encourage using existing bins that are already well-utilized.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    // Favor bins that are the "last chance" to keep the bin count low.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // We want to minimize remaining space to avoid fragmentation.
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often worse than leaving it empty (0) because it cannot fit small items.
    // We penalize values in the range [1, 10] heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if we know the next item, we penalize bins that leave 
    // just barely enough space for the current item but not the next one.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // High penalty if we block the next item from fitting in this bin
            score += 40.0 * (1.0 - (post_res / next_item_size as f64));
        }
    }

    // Dynamic adjustment based on stream progress:
    // Early in the stream, be more aggressive with packing (Best Fit).
    // Late in the stream, favor keeping bins open to consolidate remaining items.
    let consolidation_pressure = progress * 20.0;
    score += consolidation_pressure * (open_bins_count as f64 / 10.0);

    // If this is a new bin (residual == capacity), add a cost that decreases 
    // as we open more bins, but keep it high enough to prefer existing fits.
    if bin_residual == bin_capacity {
        score = 65.0 - (progress * 15.0);
    }

    // Interaction with mean_residual: avoid bins that deviate significantly 
    // from the average fill level to maintain uniform bin usage.
    let deviation = (post_res - (mean_residual - item_size as f64)).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are rarely useful for items >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. If this is a new bin, penalize it based on how many existing bins could have taken the item
    if bin_residual == bin_capacity {
        // High penalty if we open a new bin while others are available
        score += (fitting_bins_count as f64) * 40.0;
        // Global pressure: as we near the end of the stream, discourage new bins
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // 3. Best Fit logic: favor bins that leave less space (lower post_residual already handled)
        // 4. Lookahead: if next_item_size fits in post_residual, highly reward this placement
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }

        // 5. Balance the number of open bins: penalize creating too many active bins
        score += (open_bins_count as f64) * 2.0;

        // 6. Penalty for bins that deviate significantly from the mean residual (keeps bins packed similarly)
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 7. If this is the only bin that fits, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    //    reward this placement to maximize bin utilization.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.85;
    }

    // 3. Fragmentation Avoidance: If the post_residual is too small to fit typical 
    //    future items (e.g., < 10), it creates "dead space". Penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global State Awareness: If we have many open bins, prioritize closing them
    //    by filling them tighter. If we have few, be more conservative.
    let bin_pressure = (open_bins_count as f64) / (10.0 + progress * 50.0);
    score += bin_pressure * 15.0;

    // 5. New Bin Logic: Only open a new bin if the current fit is extremely poor
    //    (e.g., leaving a large, awkward gap) or if we are forced.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: decreases as the stream progresses 
        // to allow more flexibility at the end.
        score = 45.0 - (progress * 10.0);
    } else {
        // Penalize bins that are "almost full" but leave a tiny, unusable gap,
        // unless it's the last chance to fit the item.
        if fitting_bins_count == 1 && post_residual < 5 {
            score -= 10.0;
        }
    }

    // 6. Mean Residual Balancing: Favor bins that are near the global average
    //    residual to maintain a uniform distribution of fill levels.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // The base score is already post_residual. We prioritize small remainders.

    // 2. Lookahead Matching: Reward bins that can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong incentive: if this placement leaves room for the next item, reduce score
            score -= (next_item_size as f64) * 0.8;
        } else {
            // Penalty: if this placement prevents the next item from fitting, increase score
            score += (next_item_size as f64) * 0.5;
        }
    }

    // 3. Mean Residual Balancing: Avoid creating bins that are significantly below the current average
    // This helps keep bins packed to a similar density
    if (post_residual as f64) < mean_residual * 0.5 {
        score += (mean_residual - post_residual as f64) * 0.4;
    }

    // 4. New Bin Thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), calculate a "cost of opening"
    // We only open a new bin if the current fit quality is significantly worse than the average
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we are in the later stages of the stream
        let progress = step_index as f64 / total_items as f64;
        score = 25.0 + (progress * 15.0); 

        // If no other bin can fit the current item, lower the cost to open
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // 5. Efficiency Constraint:
    // Penalize keeping too many bins open simultaneously
    score += (open_bins_count as f64) * 0.2;

    score
}

