            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic Pressure: As the stream progresses, prioritize filling existing bins more tightly.
    // If fitting_bins_count is 1, this is the last chance for this bin; reduce penalty for poor fits.
    if fitting_bins_count > 1 {
        score += (open_bins_count as f64) * progress * 2.0;
    }

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
