        // High penalty for opening a new bin, which decreases as we approach the end of the stream.
        score = 45.0 - (progress * 15.0);
    } else {
        // Influence of mean_residual: If current bin is significantly better than the mean, favor it.
        score -= (mean_residual - post_res) * 0.5;
    }

    score
